/* Hmong Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Mai": "One of the most common Hmong feminine given names.", "Paj": "flower — Hmong (RPA)", "Tou": "A common Hmong masculine given name.", "Chue": "A common Hmong masculine given name.", "Ntxawm": "A Hmong feminine name in Romanized Popular Alphabet spelling.", "Yer": "A Hmong masculine name in RPA spelling.", "Vang": "One of the eighteen Hmong clans; clan names come first in traditional order.", "Lee": "A major Hmong clan name, spelled Lee in English and Ly in RPA.", "Xiong": "A major Hmong clan name.", "Moua": "A major Hmong clan name."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Mai';
console.log(lookup(q));

